'use strict';
/*
 * Builds dist/qagent-prompt-hub-local.html: the prompt hub as a single file
 * that opens in any browser with a double click, with no server.
 *
 * The local edition has every prompt, the single "Send to QAgent" message,
 * favorites, star ratings, My prompts, the troubleshooting guide and the
 * ticket comment generator (PDF and Word reading included). Each person's data
 * stays in their own browser, so there are no accounts and no admin dashboards.
 *
 * Usage: npm run build:local
 * Edit the files in public/, then rebuild. Never edit the generated file.
 */
const fs = require('node:fs');
const path = require('node:path');

const ROOT = path.resolve(__dirname, '..');
const PUB = path.join(ROOT, 'public');
const OUT = path.join(ROOT, 'dist', 'qagent-prompt-hub-local.html');

const read = (rel) => fs.readFileSync(path.join(PUB, rel), 'utf8');
const readRoot = (rel) => fs.readFileSync(path.join(ROOT, rel), 'utf8');
const dataUri = (rel) => 'data:image/png;base64,' + fs.readFileSync(path.join(PUB, rel)).toString('base64');
function inlineScript(code, name) {
  if (/<\/script/i.test(code)) throw new Error(`${name} contains "</script", which would break the inlined page.`);
  return `<script>\n${code}\n</script>`;
}
// Third-party libraries are stored as inert text and only run when someone opens a
// report in the comment generator (comment.js injects them), so the page opens fast.
function inertScript(rel, id) {
  const code = read(rel);
  if (/<\/?script/i.test(code)) throw new Error(`${rel} contains a script tag, which would break the inlined page.`);
  return `<script type="text/plain" id="${id}">\n${code}\n</script>`;
}
function swap(html, from, to) {
  if (!html.includes(from)) throw new Error(`Could not find in index.html: ${from}`);
  return html.split(from).join(to);
}

const mark = dataUri('assets/img/qualifacts-mark.png');
const logo = dataUri('assets/img/qualifacts-logo.png');
const catalog = readRoot('catalog/prompts.js');

let html = read('index.html');
html = swap(html, '<!doctype html>', '<!doctype html>\n<!-- QAgent Prompt Hub, local edition. Generated by tools/build-local.js from public/; edit those files, not this one. -->');
html = swap(html, '<link rel="stylesheet" href="assets/css/styles.css">', `<style>\n${read('assets/css/styles.css')}\n</style>`);
html = swap(html, '<script src="assets/js/boot.js"></script>', inlineScript(read('assets/js/boot.js'), 'boot.js'));
html = swap(html, '<link rel="icon" type="image/png" href="assets/img/qualifacts-mark.png">', `<link rel="icon" type="image/png" href="${mark}">`);
html = swap(html, 'src="assets/img/qualifacts-mark.png"', `src="${mark}"`);
html = swap(html, 'src="assets/img/qualifacts-logo.png"', `src="${logo}"`);
html = swap(html, '<script src="assets/js/charts.js"></script>',
  inlineScript(`window.QPH_LOCAL = true;\nwindow.QPH_ASSETS = { mark: ${JSON.stringify(mark)}, logo: ${JSON.stringify(logo)} };\n${catalog}`, 'prompts.js'));
html = swap(html, '<script src="assets/js/admin.js"></script>', '');
html = swap(html, '<script src="assets/js/comment.js"></script>', [
  inertScript('assets/vendor/pdf.min.js', 'qph-vendor-pdf'),
  inertScript('assets/vendor/pdf.worker.min.js', 'qph-vendor-pdfworker'),
  inertScript('assets/vendor/mammoth.browser.min.js', 'qph-vendor-mammoth'),
  '<!-- PDF.js 3.11.174 (Apache-2.0, Mozilla) and Mammoth 1.8.0 (BSD-2-Clause); licenses in public/assets/vendor/ -->',
  inlineScript(read('assets/js/comment.js'), 'comment.js')
].join('\n'));
html = swap(html, '<script src="assets/js/app.js"></script>', inlineScript(read('assets/js/app.js'), 'app.js'));

if (/(src|href)="assets\//.test(html)) throw new Error('A reference to assets/ was left in the page.');

fs.mkdirSync(path.dirname(OUT), { recursive: true });
fs.writeFileSync(OUT, html);
const version = (catalog.match(/version:\s*'([^']+)'/) || [])[1] || '?';
console.log(`Built ${path.relative(ROOT, OUT)} (${Math.round(fs.statSync(OUT).size / 1024)} KB, catalog v${version})`);
